# One-off helper: the candidate lemmas of game 5 and their inflected forms (plain spelling: no accents, j->i, lower case).
# Output: scripts/igra/lemmas.json, read by words-cover.ts and by the dictionary step. Forms are mechanical paradigms; homographs are left out by hand.
import json,sys
def d1(s): return [s+e for e in ['a','ae','am','arum','is','as']]
def d2(s,nom=None): return [nom or s+'us']+[s+e for e in ['i','o','um','e','orum','is','os']]
def d2n(s): return [s+e for e in ['um','i','o','a','orum','is']]
def d3(nom,s,n=False,ium=False): return [nom]+[s+e for e in (['is','i','e','a' if not ium else 'ia','um' if not ium else 'ium','ibus'] if n else ['is','i','em','e','es','um' if not ium else 'ium','ibus'])]
def d4(s): return [s+e for e in ['us','ui','um','u','uum','ibus']]
def d5(s): return [s+e for e in ['es','ei','em','e','erum','ebus']]
def adj(s,nom=None): return list(dict.fromkeys(d2(s,nom)+d1(s)+d2n(s)))
